import { cn } from "@/lib/utils";

interface Props {
  children: React.ReactNode;
  className?: string;
}
const HighlightedHeading = ({ children, className }: Props) => {
  return (
    <h2
      className={cn(
        "text-foreground relative mt-4 w-fit max-w-lg text-sm font-normal md:text-base",
        className,
      )}
    >
      <span
        className="bg-muted absolute inset-0 block h-full w-full scale-[1.04]"
        style={{ opacity: 1 }}
      >
        <span className="bg-border absolute -top-px -left-px block h-1 w-1 animate-pulse rounded-full"></span>
        <span className="bg-border absolute -top-px -right-px block h-1 w-1 animate-pulse rounded-full"></span>
        <span className="bg-border absolute -bottom-px -left-px block h-1 w-1 animate-pulse rounded-full"></span>
        <span className="bg-border absolute -right-px -bottom-px block h-1 w-1 animate-pulse rounded-full"></span>
      </span>
      <span
        className="inline-block text-base"
        style={{ opacity: 1, filter: "blur(0px)", transform: "none" }}
      >
        {children}
      </span>
    </h2>
  );
};

export default HighlightedHeading;
